function appendRenameTask(id,oldName,newName,title,behavior,parameters,expression,rawCases){
 const helper="// "+oldName+" is a persisted field name; preserve this comment.\nfunction box("+oldName+") { return {"+oldName+"}; }\nexport function "+oldName+"("+parameters+") {\n  const value = "+expression+";\n  return {"+oldName+': value, marker: "'+oldName+'", shadow: box("local")};\n}';
 const main="import { "+oldName+' } from "./helper.mjs";\nconst run = '+oldName+";\nexport function solve(...args) { return run(...args); }\nexport function local("+oldName+") { return {"+oldName+"}; }";
 const report="import { "+oldName+' as imported } from "./helper.mjs";\nexport function report(...args) { return {kind: "'+oldName+'", value: imported(...args)}; }';
 const files={"src/task.mjs":main,"src/helper.mjs":helper,"src/report.mjs":report};
 const referenceFiles={
 "src/task.mjs":main.replace("import { "+oldName+" }","import { "+newName+" }").replace("const run = "+oldName+";","const run = "+newName+";"),
 "src/helper.mjs":helper.replace("export function "+oldName+"(","export function "+newName+"("),
 "src/report.mjs":report.replace("import { "+oldName+" as imported }","import { "+newName+" as imported }")};
 const privateCases=rawCases.map(({args,expected})=>({args,expected:{[oldName]:expected,marker:oldName,shadow:{[oldName]:"local"}}}));
 codePartC4.push({id,title,category:"semantic-rename",clusterId:id,task:{stratum:"coding",
 prompt:"Rename the exported function binding "+oldName+" to "+newName+" in src/helper.mjs and update its imports and binding references in src/task.mjs and src/report.mjs. Remove the old export entirely; do not keep an alias. Preserve behavior, comments, string literals, property keys, and unrelated shadowing parameters/local bindings with the same spelling. Both caller modules must still import and execute successfully, and solve/report keep their existing APIs. The renamed helper takes "+parameters+". "+behavior+" It returns {"+oldName+': result, marker: "'+oldName+'", shadow: {'+oldName+': "local"}}. Make only the semantic rename.',
 files,privateCases,referenceFiles,evaluateSpec:{entry:"src/helper.mjs",exportName:newName,imports:["src/task.mjs","src/report.mjs"],forbiddenExports:[oldName]}}});
}
